  function isPilotPitchSection(view = state.view) {
    return view === "Pilot Pitch";
  }

  function isInsightSection(view = state.view) {
    return view === "Tender Insights" || view === "Tenders Insights" || view === "Project Insights";
  }

  function sectionForView(view) {
    if (view === "Command") return "command";
    if (view === "Autopilot") return "autopilot";
    if (view === "Time Machine") return "timeMachine";
    if (view === "Win Lab") return "winLab";
    if (view === "Decision Twin") return "decisionTwin";
    if (view === "Advisor") return "advisor";
    if (view === "Weekly Review") return "review";
    if (view === "Intake") return "intake";
    if (view === "Import") return "import";
    if (view === "Governance") return "governance";
    if (view === "Bid Desk") return "bidDesk";
    if (view === "Calendar") return "calendar";
    if (view === "Risk") return "risk";
    if (view === "Tender Insights" || view === "Tenders Insights") return "tenderInsights";
    if (view === "Project Insights") return "projectInsights";
    if (view === "Projects") return "projects";
    if (view === "Tenders") return "tenders";
    if (view === "Forecast") return "forecast";
    if (view === "Clients") return "clients";
    if (view === "Contracts") return "contracts";
    if (view === "Documents") return "documents";
    if (view === "Reminders") return "reminders";
    if (view === "Closeout") return "closeout";
    if (view === "Reports") return "reports";
    if (view === "Pilot Pitch") return "pitch";
    if (view === "Build Phase") return "buildPhase";
    if (view === "Membership") return "membership";
    return "tenders";
  }

  function userAccess(user = state.user) {
    if (!user) return [];
    if (user.role === "Admin") return ACCESS_SECTIONS.map((section) => section.key);
    return normalizeUserAccess(user);
  }

  function hasSectionAccess(key, user = state.user) {
    if (ADMIN_ONLY_SECTION_KEYS.includes(key)) return user?.role === "Admin";
    return userAccess(user).includes(key);
  }

  function canAccessView(view, user = state.user) {
    return hasSectionAccess(sectionForView(view), user);
  }

  function normalizeViewName(view) {
    const cleanView = String(view || "").trim();
    const aliases = {
      "Membership Model": "Membership",
      "Tender Insights": "Tenders Insights",
      "Pitch": "Pilot Pitch",
      "Pilot": "Pilot Pitch",
    };
    const candidate = aliases[cleanView] || cleanView;
    return ACCESS_SECTIONS.find((section) => section.view === candidate)?.view || candidate;
  }

  function viewRouteSlug(view) {
    return normalizeViewName(view)
      .toLowerCase()
      .replace(/&/g, "and")
      .replace(/[^a-z0-9]+/g, "-")
      .replace(/^-+|-+$/g, "");
  }

  function viewFromRoute(hash = window.location.hash) {
    const slug = String(hash || "").replace(/^#/, "").trim().toLowerCase();
    if (!slug) return "";
    return ACCESS_SECTIONS.find((section) => viewRouteSlug(section.view) === slug)?.view || "";
  }

  function syncViewRoute(view) {
    const slug = viewRouteSlug(view);
    if (!slug || !window.history?.replaceState) return;
    const nextHash = `#${slug}`;
    if (window.location.hash !== nextHash) {
      window.history.replaceState(null, "", nextHash);
    }
  }

  function openView(view, options = {}) {
    const cleanView = normalizeViewName(view);
    if (!cleanView) return false;
    const sectionKey = sectionForView(cleanView);
    const adminOnly = ADMIN_ONLY_SECTION_KEYS.includes(sectionKey);
    const allowed = options.skipAccessCheck || (adminOnly && canAdmin()) || canAccessView(cleanView);
    if (!allowed) {
      window.alert("This section is not enabled for your user.");
      return true;
    }
    state.view = cleanView;
    rememberRoomView(state.view);
    state.roomsOpen = false;
    state.adminToolsOpen = false;
    state.quickSearchOpen = false;
    state.quickSearch = "";
    if (state.view === "Tenders Insights") state.insightLens = "Tendering";
    if (state.view === "Project Insights") state.insightLens = "Projects";
    const typeOptions = isProjectSection() ? ["All", "Project"] : ["All", "EOI", "Tender"];
    if (!typeOptions.includes(state.filters.type)) state.filters.type = "All";
    state.selectedId = null;
    if (options.syncRoute !== false) syncViewRoute(state.view);
    render();
    scrollToTop();
    return true;
  }

  function openAdminView(view) {
    if (!canAdmin()) {
      window.alert("This admin-only section is not enabled for your user.");
      return true;
    }
    return openView(view, { skipAccessCheck: true });
  }

  function bindAdminViewButtons() {
    document.querySelectorAll("[data-action='open-admin-view'][data-view]").forEach((button) => {
      button.addEventListener("click", (event) => {
        event.preventDefault();
        event.stopPropagation();
        openAdminView(button.dataset.view);
      });
    });
  }

  function defaultViewForUser(user = state.user) {
    const access = userAccess(user);
    const section = ACCESS_SECTIONS.find((item) => access.includes(item.key));
    return section ? section.view : null;
  }

  function preferredStartView(user = state.user, memory = state.roomMemory) {
    const normalized = normalizeRoomMemory(memory);
    if (normalized.defaultView && canAccessView(normalized.defaultView, user)) return normalized.defaultView;
    return defaultViewForUser(user) || "No Access";
  }

  function setNavigationDefault(view) {
    if (!canAdmin()) return;
    const cleanView = String(view || "").trim();
    if (!canAccessView(cleanView)) return;
    const mode = roomModeForView(cleanView);
    state.roomMemory = normalizeRoomMemory({
      ...state.roomMemory,
      defaultView: cleanView,
      recentViews: [cleanView, ...state.roomMemory.recentViews.filter((item) => item !== cleanView)],
      lastMode: mode?.label || state.roomMemory.lastMode,
      presetKey: "",
    });
    persistRoomMemory();
  }

  function togglePinnedRoom(view) {
    if (!canAdmin()) return;
    const cleanView = String(view || "").trim();
    if (!canAccessView(cleanView)) return;
    const pinned = state.roomMemory.pinnedViews.includes(cleanView)
      ? state.roomMemory.pinnedViews.filter((item) => item !== cleanView)
      : [cleanView, ...state.roomMemory.pinnedViews].slice(0, 5);
    state.roomMemory = normalizeRoomMemory({
      ...state.roomMemory,
      pinnedViews: pinned,
      presetKey: "",
    });
    persistRoomMemory();
  }

  function applyNavigationPreset(presetKey) {
    if (!canAdmin()) return;
    const preset = NAVIGATION_ROLE_PRESETS.find((item) => item.key === String(presetKey || "").trim());
    if (!preset) return;
    const pinnedViews = preset.pinnedViews.filter((view) => canAccessView(view)).slice(0, 5);
    const defaultView = canAccessView(preset.defaultView) ? preset.defaultView : pinnedViews[0] || preferredStartView() || "Command";
    state.roomMemory = normalizeRoomMemory({
      ...state.roomMemory,
      presetKey: preset.key,
      defaultView,
      pinnedViews,
      recentViews: [defaultView, ...state.roomMemory.recentViews.filter((item) => item !== defaultView)],
      lastMode: preset.label,
    });
    persistRoomMemory();
  }

  function buildPresetAccessPolicyHandoff(memory = state.roomMemory) {
    const normalized = normalizeRoomMemory(memory);
    const activePreset = NAVIGATION_ROLE_PRESETS.find((preset) => preset.key === normalized.presetKey);
    const grantableKeys = new Set(GRANTABLE_ACCESS_SECTIONS.map((section) => section.key));
    const policyLaneByPreset = {
      operations: "Tracker operations",
      management: "Management review",
      commercial: "Commercial control",
      governance: "Audit evidence",
    };
    const accessModeByPreset = {
      operations: "Edit tracker fields",
      management: "Review signals",
      commercial: "Commercial rooms",
      governance: "Audit and import",
    };
    const rows = NAVIGATION_ROLE_PRESETS.map((preset) => {
      const defaultKey = sectionForView(preset.defaultView);
      const roomViews = preset.pinnedViews.filter((view) => isKnownView(view));
      const grantKeys = Array.from(
        new Set([defaultKey, ...roomViews.map((view) => sectionForView(view))].filter((key) => grantableKeys.has(key))),
      );
      return {
        key: preset.key,
        label: preset.label,
        tone: preset.tone,
        active: activePreset?.key === preset.key,
        defaultRoom: simpleRoomLabel(preset.defaultView),
        policyLane: policyLaneByPreset[preset.key] || "Workspace access",
        accessMode: accessModeByPreset[preset.key] || "Controlled access",
        grantCount: grantKeys.length,
        grantKeys,
        grantLabel: accessLabelForKeys(grantKeys) || "No grantable rooms",
        roomsLabel: roomViews.map(simpleRoomLabel).join(" / "),
        auditEvent: `navigation_preset_applied:${preset.key}`,
        note: preset.note,
      };
    });
    const activeRow = rows.find((row) => row.active) || rows[0];
    const grantCount = new Set(rows.flatMap((row) => row.grantKeys)).size;
    const summaryCards = [
      ["Policy templates", `${rows.length}`, "Operations, management, commercial, and governance", "teal"],
      ["Active preset", activeRow?.label || "Operations user", "Current browser navigation memory", activeRow?.tone || "green"],
      ["Grantable rooms", `${grantCount}`, "Future Membership access sections covered", "blue"],
      ["Audit event", "Preset applied", activeRow?.auditEvent || "navigation_preset_applied", "amber"],
    ];
    const rules = [
      ["Preset is not permission", "A preset suggests the path; Membership still grants access.", "green"],
      ["Admin approves grants", "Company admins decide who receives each room bundle.", "blue"],
      ["Commercial stays controlled", "Value, forecast, and contract rooms remain separate from tracker users.", "amber"],
      ["Audit every apply", "Each preset change should write an admin audit event.", "teal"],
    ];
    const packet = {
      schemaVersion: "pursuitdesk.presetAccessPolicyHandoff.v263",
      generatedAt: new Date().toISOString(),
      activePreset: activeRow?.key || "operations",
      digest: `${rows.length} role presets map into ${grantCount} grantable room sections with admin audit events.`,
      policyRows: rows.map((row) => ({
        presetKey: row.key,
        presetLabel: row.label,
        policyLane: row.policyLane,
        defaultRoom: row.defaultRoom,
        grantKeys: row.grantKeys,
        grantLabel: row.grantLabel,
        auditEvent: row.auditEvent,
      })),
      rules: rules.map(([label, note]) => ({ label, note })),
    };
    return {
      rows,
      summaryCards,
      rules,
      digest: packet.digest,
      downloadHref: jsonDataUri(packet),
    };
  }

  function buildPresetPolicyApplyReceipt(memory = state.roomMemory) {
    const normalized = normalizeRoomMemory(memory);
    const activePreset = NAVIGATION_ROLE_PRESETS.find((preset) => preset.key === normalized.presetKey) || NAVIGATION_ROLE_PRESETS[0];
    const appliedBy = state.user?.name || "PursuitDesk Admin";
    const appliedAt = new Date();
    const appliedLabel = formatDate(appliedAt.toISOString().slice(0, 10));
    const defaultRoom = normalized.defaultView || activePreset.defaultView || "Command";
    const visiblePins = (normalized.pinnedViews.length ? normalized.pinnedViews : activePreset.pinnedViews)
      .filter((view) => isKnownView(view))
      .slice(0, 5);
    const afterRooms = Array.from(new Set([defaultRoom, ...visiblePins].filter(Boolean)));
    const beforeRooms = ["Command", "Tenders", "Projects", "Weekly Review", "Reports"].filter((view) => isKnownView(view));
    const changedRooms = afterRooms.filter((view) => !beforeRooms.includes(view));
    const grantableKeys = new Set(GRANTABLE_ACCESS_SECTIONS.map((section) => section.key));
    const grantKeys = Array.from(
      new Set(afterRooms.map((view) => sectionForView(view)).filter((key) => grantableKeys.has(key))),
    );
    const receiptId = `PD-PRESET-APPLY-${String(activePreset.key || "operations").toUpperCase()}-${appliedAt.toISOString().slice(0, 10).replaceAll("-", "")}`;
    const auditEvent = `navigation_preset_apply_receipt:${activePreset.key}`;
    const changedLabel = changedRooms.length ? changedRooms.map(simpleRoomLabel).join(" / ") : "No new rooms";
    const grantLabel = accessLabelForKeys(grantKeys) || "No grant change";
    const receiptCards = [
      ["Applied preset", activePreset.label, `${appliedBy} applied this browser start path.`, activePreset.tone || "teal"],
      ["Rooms changed", changedRooms.length || "0", changedLabel, changedRooms.length ? "blue" : "green"],
      ["Grant proposal", grantKeys.length, grantLabel, "green"],
      ["Audit packet", "Ready", auditEvent, "amber"],
    ];
    const receiptRows = [
      ["Default start", simpleRoomLabel(defaultRoom), "The first room this role should open.", "green"],
      ["Pinned rooms", visiblePins.map(simpleRoomLabel).join(" / ") || "None", "Quick rooms shown before the full menu.", "teal"],
      ["Proposed grants", grantLabel, "Future Membership can convert this into access sections.", "blue"],
      ["Audit event", auditEvent, "Backend should write this event when the preset is applied.", "amber"],
    ];
    const checklist = [
      ["Apply is reversible", "Reset memory returns the browser to Operations defaults.", "green"],
      ["Membership still rules", "Preset does not override actual user access grants.", "blue"],
      ["Admin owns change", `${appliedBy} is recorded as the receipt owner for demo audit.`, "teal"],
      ["Commercial stays separate", "Commercial grants are proposed, not silently given to tracker users.", "amber"],
    ];
    const digest = [
      `Preset Policy Apply Receipt ${receiptId}`,
      `Applied preset: ${activePreset.label}`,
      `Applied by: ${appliedBy}`,
      `Applied on: ${appliedLabel}`,
      `Default room: ${simpleRoomLabel(defaultRoom)}`,
      `Pinned rooms: ${visiblePins.map(simpleRoomLabel).join("; ") || "None"}`,
      `Proposed grants: ${grantLabel}`,
      `Changed rooms from operations baseline: ${changedLabel}`,
      `Audit event: ${auditEvent}`,
    ].join("\n");
    const packet = {
      schemaVersion: "pursuitdesk.presetPolicyApplyReceipt.v266",
      generatedAt: appliedAt.toISOString(),
      receiptId,
      company: state.data.company.name,
      appliedBy,
      activePreset: activePreset.key,
      defaultRoom,
      pinnedViews: visiblePins,
      changedRooms,
      grantKeys,
      grantLabel,
      auditEvent,
      receiptRows: receiptRows.map(([label, value, note, tone]) => ({ label, value, note, tone })),
      checklist: checklist.map(([label, note, tone]) => ({ label, note, tone })),
      digest,
      nextBackendFields: [
        "navigation_preset_apply_receipt_id",
        "tenant_id",
        "applied_by_user_id",
        "preset_key",
        "before_room_json",
        "after_room_json",
        "proposed_grant_keys",
        "membership_approval_state",
        "navigation_preset_apply_audit_event",
      ],
    };
    return {
      receiptId,
      activePreset,
      appliedBy,
      appliedAt: appliedAt.toISOString(),
      defaultRoom,
      pinnedViews: visiblePins,
      changedRooms,
      grantKeys,
      grantLabel,
      auditEvent,
      cards: receiptCards,
      rows: receiptRows,
      checklist,
      digest,
      downloadHref: jsonDataUri(packet),
    };
  }

  function buildPresetGrantApprovalQueue(memory = state.roomMemory, applyReceipt = buildPresetPolicyApplyReceipt(memory)) {
    const normalized = normalizeRoomMemory(memory);
    const activePreset = applyReceipt.activePreset || NAVIGATION_ROLE_PRESETS.find((preset) => preset.key === normalized.presetKey) || NAVIGATION_ROLE_PRESETS[0];
    const generatedAt = new Date();
    const approvalId = `PD-PRESET-GRANT-${String(activePreset.key || "operations").toUpperCase()}-${generatedAt.toISOString().slice(0, 10).replaceAll("-", "")}`;
    const proposedKeys = Array.isArray(applyReceipt.grantKeys) ? applyReceipt.grantKeys : [];
    const sensitiveKeys = new Set(["advisor", "autopilot", "timeMachine", "winLab", "decisionTwin", "tenderInsights", "projectInsights", "forecast", "clients", "contracts"]);
    const rows = proposedKeys.map((key) => {
      const section = GRANTABLE_ACCESS_SECTIONS.find((item) => item.key === key) || ACCESS_SECTIONS.find((item) => item.key === key);
      const label = section?.label || key;
      const needsManager = sensitiveKeys.has(key);
      const decision = needsManager ? "Hold" : "Approve";
      return {
        grantKey: key,
        sectionLabel: label,
        decision,
        reviewer: needsManager ? "Manager approval" : "Admin release",
        reason: needsManager
          ? "Insight, commercial, or intelligence room needs explicit management approval before access changes."
          : "Operational room matches the preset and can be released after admin confirmation.",
        effect: needsManager ? "Keep proposed until Membership approval is recorded." : "Convert into active room access after approval.",
        tone: needsManager ? "amber" : "green",
      };
    });
    rows.push({
      grantKey: "membership",
      sectionLabel: "Membership Model",
      decision: "Reject",
      reviewer: "Company owner",
      reason: "Billing, subscription, and seat controls stay admin-only and cannot be granted by a navigation preset.",
      effect: "No access change. Grant only from the Membership Model when the account owner approves it.",
      tone: "red",
    });
    const approveCount = rows.filter((row) => row.decision === "Approve").length;
    const holdCount = rows.filter((row) => row.decision === "Hold").length;
    const rejectCount = rows.filter((row) => row.decision === "Reject").length;
    const cards = [
      ["Queue state", "Approval required", `${rows.length} proposed access decisions`, "blue"],
      ["Approve", approveCount, "Operational rooms ready for release", "green"],
      ["Hold", holdCount, "Management or commercial rooms need review", "amber"],
      ["Reject", rejectCount, "Admin-only areas blocked", "red"],
    ];
    const rules = [
      ["Preset suggests", "The preset can propose access sections, but it does not activate them.", "blue"],
      ["Admin approves", "Company admin must approve every grant before Membership changes.", "green"],
      ["Commercial holds", "Insight, value, contract, and client rooms remain held until management approves.", "amber"],
      ["Membership protected", "Billing and seat control remains admin-only by rule.", "red"],
    ];
    const digest = [
      `Preset Grant Approval Queue ${approvalId}`,
      `Source receipt: ${applyReceipt.receiptId}`,
      `Preset: ${activePreset.label}`,
      `Proposed grants: ${applyReceipt.grantLabel || accessLabelForKeys(proposedKeys) || "No grant change"}`,
      `Approve: ${approveCount}`,
      `Hold: ${holdCount}`,
      `Reject: ${rejectCount}`,
      "Membership access changes only after an approved decision row is written.",
    ].join("\n");
    const packet = {
      schemaVersion: "pursuitdesk.presetGrantApprovalQueue.v269",
      generatedAt: generatedAt.toISOString(),
      approvalId,
      sourceReceiptId: applyReceipt.receiptId,
      company: state.data.company.name,
      presetKey: activePreset.key,
      presetLabel: activePreset.label,
      proposedGrantKeys: proposedKeys,
      decisions: rows.map((row) => ({
        grantKey: row.grantKey,
        sectionLabel: row.sectionLabel,
        decision: row.decision,
        reviewer: row.reviewer,
        reason: row.reason,
        effect: row.effect,
      })),
      rules: rules.map(([label, note, tone]) => ({ label, note, tone })),
      digest,
      nextBackendFields: [
        "preset_grant_approval_queue_id",
        "navigation_preset_apply_receipt_id",
        "tenant_id",
        "target_user_id",
        "proposed_grant_key",
        "grant_decision_state",
        "grant_reviewer_role",
        "approval_reason",
        "membership_access_change_state",
        "grant_approval_audit_event",
      ],
    };
    return {
      approvalId,
      approveCount,
      holdCount,
      rejectCount,
      cards,
      rows,
      rules,
      digest,
      downloadHref: jsonDataUri(packet),
    };
  }

  function buildPresetGrantFollowUpTasks(memory = state.roomMemory, applyReceipt = buildPresetPolicyApplyReceipt(memory), grantApprovalQueue = buildPresetGrantApprovalQueue(memory, applyReceipt)) {
    const generatedAt = new Date();
    const taskPackId = `PD-GRANT-FOLLOWUP-${String(applyReceipt.activePreset?.key || "operations").toUpperCase()}-${generatedAt.toISOString().slice(0, 10).replaceAll("-", "")}`;
    const dueLabel = (offsetDays) => {
      const dueDate = new Date(generatedAt);
      dueDate.setDate(dueDate.getDate() + offsetDays);
      return formatDate(dueDate.toISOString().slice(0, 10));
    };
    const taskRows = grantApprovalQueue.rows.map((row, index) => {
      const decision = row.decision;
      const isApprove = decision === "Approve";
      const isHold = decision === "Hold";
      const isReject = decision === "Reject";
      return {
        taskId: `${taskPackId}-${String(index + 1).padStart(2, "0")}`,
        sectionLabel: row.sectionLabel,
        decision,
        owner: isApprove ? "Company admin" : isHold ? row.reviewer : "Account owner",
        due: isApprove ? dueLabel(1) : isHold ? dueLabel(2) : dueLabel(0),
        lane: isApprove ? "Release access" : isHold ? "Request signoff" : "Keep blocked",
        action: isApprove
          ? `Release ${row.sectionLabel} in Membership access, then confirm the user can open only the approved room.`
          : isHold
            ? `Keep ${row.sectionLabel} proposed and request a management approval note before any Membership change.`
            : `Keep ${row.sectionLabel} disabled and record why the preset cannot grant it.`,
        reminder: isApprove
          ? "Write the access-change audit event after Membership is updated."
          : isHold
            ? "Review again after the manager gives approve, hold, or reject."
            : "Do not reopen this grant from navigation presets; only the account owner can change it.",
        tone: isApprove ? "green" : isHold ? "amber" : "red",
      };
    });
    const releaseCount = taskRows.filter((row) => row.decision === "Approve").length;
    const signoffCount = taskRows.filter((row) => row.decision === "Hold").length;
    const blockedCount = taskRows.filter((row) => row.decision === "Reject").length;
    const primaryTask = taskRows.find((row) => row.decision === "Hold") || taskRows.find((row) => row.decision === "Approve") || taskRows[0];
    const cards = [
      ["Task pack", taskRows.length, "Every approval decision now has an admin follow-up action.", "teal"],
      ["Release now", releaseCount, "Operational rooms can be activated from Membership.", "green"],
      ["Needs signoff", signoffCount, "Management or commercial rooms stay held until reviewed.", "amber"],
      ["Blocked", blockedCount, "Admin-only areas remain protected.", "red"],
    ];
    const checks = [
      ["Membership is source", "Navigation presets propose access, but Membership still performs the real change.", "green"],
      ["Held rooms stay held", "Commercial, client, contract, and intelligence sections need a manager note before release.", "amber"],
      ["Billing stays protected", "Membership Model cannot be granted from a navigation preset.", "red"],
      ["Audit every movement", "Each release, hold, or rejection becomes an audit reminder for the backend.", "blue"],
    ];
    const digest = [
      `Preset Grant Follow-up Tasks ${taskPackId}`,
      `Source approval queue: ${grantApprovalQueue.approvalId}`,
      `Source apply receipt: ${applyReceipt.receiptId}`,
      `Primary task: ${primaryTask.lane} / ${primaryTask.sectionLabel} / ${primaryTask.owner} / due ${primaryTask.due}`,
      `Release: ${releaseCount}`,
      `Signoff: ${signoffCount}`,
      `Blocked: ${blockedCount}`,
      `Task rows: ${taskRows.map((row) => `${row.decision} / ${row.sectionLabel} / ${row.owner} / ${row.due} / ${row.action}`).join("; ")}`,
      "Rule: follow-up tasks may change Membership access only after a recorded approval decision and audit reminder.",
    ].join("\n");
    const email = [
      `Subject: PursuitDesk access approval follow-up - ${primaryTask.sectionLabel}`,
      "",
      `Hi ${primaryTask.owner},`,
      "",
      `The preset approval queue created a follow-up task: ${primaryTask.action}`,
      `Due: ${primaryTask.due}.`,
      `Reminder: ${primaryTask.reminder}`,
      "",
      "Please keep Membership as the source of access control and record the audit event after the task is closed.",
      "",
      "Regards,",
      "PursuitDesk team",
    ].join("\n");
    const packet = {
      schemaVersion: "pursuitdesk.presetGrantFollowUpTasks.v272",
      generatedAt: generatedAt.toISOString(),
      taskPackId,
      sourceApprovalId: grantApprovalQueue.approvalId,
      sourceReceiptId: applyReceipt.receiptId,
      company: state.data.company.name,
      presetKey: applyReceipt.activePreset?.key || "operations",
      presetLabel: applyReceipt.activePreset?.label || "Operations user",
      primaryTask,
      releaseCount,
      signoffCount,
      blockedCount,
      cards: cards.map(([label, value, note, tone]) => ({ label, value, note, tone })),
      tasks: taskRows,
      checks: checks.map(([label, note, tone]) => ({ label, note, tone })),
      digest,
      email,
      nextBackendFields: [
        "preset_grant_follow_up_task_pack_id",
        "preset_grant_approval_queue_id",
        "navigation_preset_apply_receipt_id",
        "target_user_id",
        "access_task_state",
        "access_task_owner_role",
        "access_task_due_at",
        "membership_access_change_id",
        "grant_follow_up_audit_event",
      ],
    };
    return {
      taskPackId,
      primaryTask,
      releaseCount,
      signoffCount,
      blockedCount,
      cards,
      taskRows,
      checks,
      digest,
      email,
      downloadHref: jsonDataUri(packet),
    };
  }

  function buildPresetGrantExecutionReceipt(memory = state.roomMemory, applyReceipt = buildPresetPolicyApplyReceipt(memory), grantApprovalQueue = buildPresetGrantApprovalQueue(memory, applyReceipt), grantFollowUpTasks = buildPresetGrantFollowUpTasks(memory, applyReceipt, grantApprovalQueue)) {
    const executedAt = new Date();
    const receiptId = `PD-GRANT-EXEC-${String(applyReceipt.activePreset?.key || "operations").toUpperCase()}-${executedAt.toISOString().slice(0, 10).replaceAll("-", "")}`;
    const executionRows = grantFollowUpTasks.taskRows.map((task, index) => {
      const released = task.decision === "Approve";
      const held = task.decision === "Hold";
      return {
        receiptRowId: `${receiptId}-${String(index + 1).padStart(2, "0")}`,
        sectionLabel: task.sectionLabel,
        taskId: task.taskId,
        owner: task.owner,
        due: task.due,
        outcome: released ? "Released" : held ? "Held again" : "Blocked",
        evidence: released
          ? "Membership access change queued with section-limited verification."
          : held
            ? "Manager approval note still required before access can change."
            : "Admin-only section remains blocked with reason retained.",
        auditEvent: released
          ? `membership_access_released:${task.sectionLabel}`
          : held
            ? `membership_access_hold:${task.sectionLabel}`
            : `membership_access_blocked:${task.sectionLabel}`,
        tone: released ? "green" : held ? "amber" : "red",
      };
    });
    const releasedCount = executionRows.filter((row) => row.outcome === "Released").length;
    const heldAgainCount = executionRows.filter((row) => row.outcome === "Held again").length;
    const blockedCount = executionRows.filter((row) => row.outcome === "Blocked").length;
    const auditReadyCount = executionRows.filter((row) => row.auditEvent).length;
    const cards = [
      ["Receipt", "Execution ready", `${executionRows.length} access task outcomes`, "blue"],
      ["Released", releasedCount, "Operational rooms can move to Membership access.", "green"],
      ["Held again", heldAgainCount, "Sensitive rooms still need management signoff.", "amber"],
      ["Blocked", blockedCount, "Admin-only grants stay protected.", "red"],
    ];
    const closeRules = [
      ["Verify user view", "After release, preview the target user before telling the team access is live.", "green"],
      ["Do not auto-release holds", "Held rooms need a fresh management decision before Membership changes.", "amber"],
      ["Keep billing closed", "Membership Model remains outside preset grants and cannot be released from Rooms.", "red"],
      ["Write audit memory", `${auditReadyCount} receipt rows define the backend audit events to store.`, "blue"],
    ];
    const digest = [
      `Preset Grant Execution Receipt ${receiptId}`,
      `Source task pack: ${grantFollowUpTasks.taskPackId}`,
      `Source approval queue: ${grantApprovalQueue.approvalId}`,
      `Released: ${releasedCount}`,
      `Held again: ${heldAgainCount}`,
      `Blocked: ${blockedCount}`,
      `Execution rows: ${executionRows.map((row) => `${row.outcome} / ${row.sectionLabel} / ${row.owner} / ${row.auditEvent}`).join("; ")}`,
      "Rule: execution receipt is proof only; Membership remains the system of record for actual access changes.",
    ].join("\n");
    const packet = {
      schemaVersion: "pursuitdesk.presetGrantExecutionReceipt.v273",
      executedAt: executedAt.toISOString(),
      receiptId,
      sourceTaskPackId: grantFollowUpTasks.taskPackId,
      sourceApprovalId: grantApprovalQueue.approvalId,
      sourceReceiptId: applyReceipt.receiptId,
      company: state.data.company.name,
      presetKey: applyReceipt.activePreset?.key || "operations",
      presetLabel: applyReceipt.activePreset?.label || "Operations user",
      releasedCount,
      heldAgainCount,
      blockedCount,
      auditReadyCount,
      cards: cards.map(([label, value, note, tone]) => ({ label, value, note, tone })),
      executionRows,
      closeRules: closeRules.map(([label, note, tone]) => ({ label, note, tone })),
      digest,
      nextBackendFields: [
        "preset_grant_execution_receipt_id",
        "preset_grant_follow_up_task_pack_id",
        "preset_grant_approval_queue_id",
        "target_user_id",
        "section_key",
        "access_execution_outcome",
        "membership_access_change_id",
        "verification_preview_user_id",
        "grant_execution_audit_event",
      ],
    };
    return {
      receiptId,
      releasedCount,
      heldAgainCount,
      blockedCount,
      auditReadyCount,
      cards,
      executionRows,
      closeRules,
      digest,
      downloadHref: jsonDataUri(packet),
    };
  }

  function clearNavigationMemory() {
    if (!canAdmin()) return;
    state.roomMemory = normalizeRoomMemory({
      defaultView: "Command",
      pinnedViews: ["Command", "Tenders", "Projects", "Weekly Review", "Reports"].filter((view) => canAccessView(view)),
      presetKey: "operations",
    });
    persistRoomMemory();
  }

  function refreshSessionUser() {
    if (!state.user) return;
    const current = state.data.users.find((user) => user.id === state.user.id);
    if (!current) {
      state.user = null;
      if (!isAccessPreviewing()) persistSession(null);
      return;
    }
    state.user = {
      id: current.id,
      companyId: current.companyId,
      name: current.name,
      email: current.email,
      role: current.role,
      access: normalizeUserAccess(current),
    };
    if (!isAccessPreviewing()) persistSession(state.user);
  }

  function ensureAccessibleView() {
    refreshSessionUser();
    if (!state.user) return;
    if (state.view === "All") state.view = "Tenders";
    if (state.view === "Insights" || state.view === "Tender Insights") state.view = "Tenders Insights";
    if (!canAccessView(state.view)) state.view = preferredStartView() || "No Access";
  }

  function escapeHtml(value) {
    return String(value ?? "")
      .replaceAll("&", "&amp;")
      .replaceAll("<", "&lt;")
      .replaceAll(">", "&gt;")
      .replaceAll('"', "&quot;")
      .replaceAll("'", "&#039;");
  }

  function compactText(value, maxLength = 92) {
    const text = String(value ?? "").trim();
    if (text.length <= maxLength) return text;
    return `${text.slice(0, maxLength - 3).trim()}...`;
  }

  function showTransientNotice(message) {
    document.querySelector(".app-toast")?.remove();
    const toast = document.createElement("div");
    toast.className = "app-toast";
    toast.textContent = message;
    document.body.appendChild(toast);
    requestAnimationFrame(() => toast.classList.add("is-visible"));
    window.setTimeout(() => {
      toast.classList.remove("is-visible");
      window.setTimeout(() => toast.remove(), 220);
    }, 2200);
  }

  function copyTextToClipboard(text, message = "Copied.") {
    if (!text) return;
    const fallbackCopy = () => {
      const textarea = document.createElement("textarea");
      textarea.value = text;
      textarea.setAttribute("readonly", "");
      textarea.style.position = "fixed";
      textarea.style.left = "-9999px";
      textarea.style.top = "0";
      document.body.appendChild(textarea);
      textarea.select();
      try {
        document.execCommand("copy");
        showTransientNotice(message);
      } catch (error) {
        showTransientNotice("Copy blocked by browser.");
      } finally {
        textarea.remove();
      }
    };

    if (navigator.clipboard && window.isSecureContext) {
      navigator.clipboard.writeText(text).then(() => showTransientNotice(message)).catch(fallbackCopy);
      return;
    }
    fallbackCopy();
  }

  function normalize(value) {
    return String(value ?? "").trim().toLowerCase();
  }

  function formatDate(value) {
    if (!value) return "";
    const date = new Date(`${value}T00:00:00`);
    if (Number.isNaN(date.getTime())) return value;
    return date.toLocaleDateString("en-GB", {
      day: "2-digit",
      month: "short",
      year: "numeric",
    });
  }

  function statusClass(status) {
    const key = normalize(status).replaceAll(" ", "-");
    if (["active", "ongoing", "submitted", "pending"].includes(key)) return `status-${key}`;
    if (["awarded", "completed"].includes(key)) return `status-${key}`;
    if (["cancelled", "regret"].includes(key)) return `status-${key}`;
    return "status-default";
  }

  function uniqueOptions(field) {
    const values = companyRecords()
      .map((record) => record[field])
      .filter(Boolean)
      .map(String);
    return Array.from(new Set(values)).sort((a, b) => a.localeCompare(b));
  }

  function filterRecords() {
    let records = companyRecords();
    if (isTenderSection()) {
      records = records.filter((record) => record.type === "Tender" || record.type === "EOI");
    }
    if (isProjectSection()) {
      records = records.filter((record) => record.type === "Project");
    }
    if (state.filters.type !== "All") {
      records = records.filter((record) => record.type === state.filters.type);
    }
    if (state.filters.status !== "All") {
      records = records.filter((record) => record.status === state.filters.status);
    }
    if (state.filters.category !== "All") {
      records = records.filter((record) => record.category === state.filters.category);
    }
    const lane = state.filters.lane || "All lanes";
    if (lane !== "All lanes") {
      records = records.filter((record) => recordMatchesLane(record, lane));
    }
    const search = normalize(state.filters.search);
    if (search) {
      records = records.filter((record) =>
        [
          record.reference,
          record.client,
          record.clientGroup,
          record.title,
          record.category,
          record.status,
          record.owner,
          record.latestActivity,
          record.sourceSheet,
        ]
          .map(normalize)
          .join(" ")
          .includes(search),
      );
    }
    return records;
  }

  function recordMatchesLane(record, lane) {
    const date = parseRecordDate(record.endDate);
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    if (lane === "Needs decision") {
      return !isClosedRecord(record) && ["Active", "Pending", "Submitted"].includes(record.status);
    }
    if (lane === "Due watch") {
      const days = recordDueDays(record);
      return !isClosedRecord(record) && days !== null && days <= 30;
    }
    if (lane === "Past due") {
      return !isClosedRecord(record) && date && date < today;
    }
    if (lane === "No due date") {
      return !isClosedRecord(record) && !record.endDate;
    }
    if (lane === "Missing owner") {
      return !isClosedRecord(record) && !record.owner;
    }
    if (lane === "Missing category") {
      return !isClosedRecord(record) && !record.category;
    }
    if (lane === "Missing reference") {
      return !isClosedRecord(record) && !record.reference;
    }
    if (lane === "Ready rhythm") {
      return !isClosedRecord(record) && Boolean(record.reference && record.client && record.title && record.status && record.owner && record.category && record.endDate);
    }
    return true;
  }

  function metrics() {
    const records = companyRecords();
    const activeTenders = records.filter(
      (record) =>
        (record.type === "Tender" || record.type === "EOI") &&
        !["Awarded", "Completed", "Cancelled", "Regret"].includes(record.status),
    ).length;
    const ongoingProjects = records.filter(
      (record) => record.type === "Project" && normalize(record.status) === "ongoing",
    ).length;
    const awarded = records.filter((record) => record.status === "Awarded").length;
    const completed = records.filter((record) => record.status === "Completed").length;
    const tenders = records.filter((record) => record.type === "Tender").length;
    const eois = records.filter((record) => record.type === "EOI").length;
    const projects = records.filter((record) => record.type === "Project").length;
    const pending = records.filter((record) => record.status === "Pending").length;
    const submitted = records.filter((record) => record.status === "Submitted").length;
    const risk = records.filter((record) => ["Cancelled", "Regret"].includes(record.status)).length;
    const users = state.data.users.filter((user) => user.companyId === state.user.companyId);
    return {
      activeTenders,
      ongoingProjects,
      awarded,
      completed,
      tenders,
      eois,
      projects,
      pending,
      submitted,
      risk,
      seats: users.length,
      bill: Math.max(STARTER_WORKSPACE_BASE, users.length * state.data.company.pricePerUser),
      totalRecords: records.length,
      winProgress: records.length ? Math.round(((awarded + completed) / records.length) * 100) : 0,
    };
  }

  function pricingProjection(company = state.data.company) {
    const seats = Math.min(100, Math.max(1, Number(state.pricingSeats) || 10));
    const billingTerm = BILLING_TERMS.includes(state.billingTerm) ? state.billingTerm : "Monthly";
    const plan = getMembershipPlan();
    const billing = calculateMembershipBilling(plan, seats, billingTerm);
    return {
      ...billing,
      seats,
      plan,
      perUser: plan.extraSeat || company.pricePerUser,
      managerSeat: plan.managerSeat || BILLING_MANAGER_SEAT_PRICE,
      base: plan.base,
      includedSeats: plan.includedSeats,
      includedManagers: plan.includedManagers,
      billingTerm,
    };
  }

  function getSelected(records) {
    if (!records.length) return null;
    const current = records.find((record) => record.id === state.selectedId);
    if (current) return current;
    state.selectedId = records[0].id;
    return records[0];
  }

