  function renderSimpleRoomsNavigator() {
    const cards = ROOM_NAVIGATOR_GROUPS.map((group) => {
      const availableRooms = group.rooms.filter((view) => canAccessView(view));
      if (!availableRooms.length) return "";
      const primaryView = canAccessView(group.primaryView) ? group.primaryView : availableRooms[0];
      const primaryLabel = simpleRoomLabel(primaryView);
      const active = availableRooms.includes(state.view);
      return `
        <article class="rooms-guide-card tone-${escapeHtml(group.tone)} ${active ? "active" : ""}">
          <div>
            <span>${escapeHtml(group.label)}</span>
            <p>${escapeHtml(group.note)}</p>
          </div>
          <button class="rooms-guide-open" type="button" data-view="${escapeHtml(primaryView)}">Open ${escapeHtml(primaryLabel)}</button>
          <div class="rooms-guide-pills" aria-label="${escapeHtml(group.label)} rooms">
            ${availableRooms
              .slice(0, 5)
              .map((view) => `<button type="button" data-view="${escapeHtml(view)}">${escapeHtml(simpleRoomLabel(view))}</button>`)
              .join("")}
          </div>
        </article>
      `;
    }).filter(Boolean);
    if (!cards.length) return "";
    return `
      <section class="rooms-simple-guide" aria-label="Simple room guide">
        <div class="rooms-simple-head">
          <span>Simple room guide</span>
          <strong>Choose one work mode first</strong>
        </div>
        <div class="rooms-guide-grid">
          ${cards.join("")}
        </div>
      </section>
    `;
  }

  function simpleRoomLabel(view) {
    const section = ACCESS_SECTIONS.find((item) => item.view === view);
    return section ? navSectionLabel(section) : String(view || "");
  }

  function isRenderableNavSection(section) {
    return Boolean(
      section &&
      String(section.key || "").trim() &&
      String(section.view || "").trim() &&
      navSectionLabel(section)
    );
  }

  function navSectionLabel(section) {
    return String(section?.label || section?.view || "").trim();
  }

  function roomNavTone(view) {
    return {
      "Time Machine": "blue",
      "Win Lab": "green",
      "Decision Twin": "teal",
      Intake: "teal",
      Import: "amber",
      Governance: "green",
      "Bid Desk": "blue",
      Calendar: "amber",
      Risk: "red",
      "Tenders Insights": "teal",
      "Project Insights": "blue",
      Forecast: "green",
      Clients: "green",
      Contracts: "amber",
      Documents: "blue",
      Reminders: "red",
      Closeout: "green",
    }[view] || "teal";
  }

  function roomNavNote(view) {
    return {
      "Time Machine": "Scenario simulation",
      "Win Lab": "Bid strategy lab",
      "Decision Twin": "Decision replay",
      Intake: "Request front door",
      Import: "Excel import control",
      Governance: "Audit and access",
      "Bid Desk": "Bid/no-bid execution",
      Calendar: "Dates and pressure",
      Risk: "Risk register",
      "Tenders Insights": "Tender analytics",
      "Project Insights": "Project analytics",
      Forecast: "Weighted pipeline",
      Clients: "Relationship heat",
      Contracts: "Commercial proof",
      Documents: "Evidence packs",
      Reminders: "Follow-up queue",
      Closeout: "Archive control",
    }[view] || "Operating room";
  }

  function sectionRecords(view = state.view) {
    const records = companyRecords();
    if (isTenderSection(view)) return records.filter((record) => record.type === "Tender" || record.type === "EOI");
    if (isProjectSection(view)) return records.filter((record) => record.type === "Project");
    return records;
  }

  function sectionMetrics(records) {
    const due = buildDueBuckets(records);
    const dueWatch = due.find((bucket) => bucket.label === "Past due").value + due.find((bucket) => bucket.label === "Next 30 days").value;
    const closed = records.filter(isClosedRecord).length;
    return {
      total: records.length,
      active: records.filter((record) => record.status === "Active").length,
      ongoing: records.filter((record) => record.status === "Ongoing").length,
      pending: records.filter((record) => record.status === "Pending").length,
      submitted: records.filter((record) => record.status === "Submitted").length,
      awarded: records.filter((record) => record.status === "Awarded").length,
      completed: records.filter((record) => record.status === "Completed").length,
      closed,
      dueWatch,
      open: records.filter((record) => !isClosedRecord(record)).length,
      value: sumAmounts(records),
    };
  }

