    const ledgerState =
      ledgerDecision === "Reusable candidate" && proofReady
        ? "Cross-tenant candidate"
        : ledgerDecision === "Tenant ledger"
          ? "Tenant learning ledger"
          : ledgerDecision === "Retune ledger"
